import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { InjectorsRatingComponent } from './injectors-rating.component';

const routes: Routes = [{ path: '', component: InjectorsRatingComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class InjectorsRatingRoutingModule { }
