import { Component, OnInit, ViewChild } from '@angular/core';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { Urls } from '../../../../core/common/Urls';
import { GResponse } from '../../../../core/common/GResponse';
import { G } from '../../../../core/common/G';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { IonContent, AlertController, LoadingController, ToastController } from '@ionic/angular';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from '../../../../data/service/site/Slider.service';

@Component({
  selector: 'app-injectors-rating',
  templateUrl: './injectors-rating.component.html',
  styleUrls: ['./injectors-rating.component.scss']
})
export class InjectorsRatingComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;

  isShow = false;
  isCheck = true;
  queryText = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  tunerPlusInj: string | SafeUrl = 'zYFuN';

  unitSelected = 'cc/min';

  form: FormGroup;
  form2: FormGroup;
  injCc = 170.1;
  injG = 122.4;
  injLb = 16.2;
  injNewSizeCc = 252;
  injNewSizeG = 181.3;
  injNewSizeLb = 24;

  constructor(
    private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private siteService: SliderService,
    private courseService: CourseService
  ) {
    this.isShow = false;
    this.check();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(11).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;

                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
    this.tunerPlusInj = G.TunerPlusInj;

    this.form = this.fb.group({
      n: [4, [Validators.required, Validators.min(1), Validators.max(10000)]],
      h: [110, [Validators.required, Validators.min(1), Validators.max(100000)]]
    });

    this.form2 = this.fb.group({
      size: [180, [Validators.required, Validators.min(1), Validators.max(100000)]],
      oldPressure: [43.5, [Validators.required, Validators.min(1), Validators.max(100000)]],
      newPressure: [85, [Validators.required, Validators.min(1), Validators.max(100000)]]
    });
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  onCalc2() {

    if (!this.form.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          let size = this.form2.value.size;

          if (this.unitSelected === 'cc/min') {
            size /= 10.5;
          }
          else if (this.unitSelected === 'g/min') {
            size *= 1.39;
            size /= 10.5;
          }

          const your_flow = this.compute_flow(size, this.form2.value.oldPressure, this.form2.value.newPressure);
          this.injNewSizeLb = Math.round(your_flow * 10) / 10;

          this.injNewSizeCc = +(this.injNewSizeLb * 10.5).toFixed(3);
          this.injNewSizeG = +(this.injNewSizeCc / 1.39).toFixed(1);
          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  compute_flow(old_fuel_flow, old_pressure, new_pressure) {
    const flowndx = old_fuel_flow * Math.sqrt(new_pressure / old_pressure);
    return flowndx;
  }

  unitChanged() {

    if (this.unitSelected === 'lbs/hr') {

    } else {

    }
  }

  onReset2() {

    this.injNewSizeCc = 252;
    this.injNewSizeG = 181.3;
    this.injNewSizeLb = 24;
    this.form2.setValue({
      size: 180,
      oldPressure: 43.5,
      newPressure: 85
    });
  }

  onCalc() {

    if (!this.form.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          const hp = this.form.value.h;
          const ninj = this.form.value.n;
          const yourpph = this.pph(hp, ninj);
          this.injLb = Math.round(yourpph * 10) / 10;

          this.injCc = +(this.injLb * 10.5).toFixed(1);
          this.injG = +(this.injCc / 1.39).toFixed(1);
          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  pph(hp, ninj) {
    const pphndx = hp / ninj * 0.588;
    return pphndx;
  }

  onReset() {

    this.injCc = 170.1;
    this.injG = 122.4;
    this.injLb = 16.2;
    this.form.setValue({
      n: 4,
      h: 110
    });
  }

  onInfo(type: string) {

    switch (type) {
      case 'n':
        this.presentActiveAlertConfirm('تعداد انژکتوره بکار رفته که ممکن است بیشتر از تعداد سیلندر هم باشد');
        break;
      case 'h':
        this.presentActiveAlertConfirm('توان موتور بر سر فلایول برحسب اسب بخار. معمولا توان بر سر فلایول حدود 10 الی 30 درصد بیشتر از سر چرخ است');
        break;
      case 'size':
        this.presentActiveAlertConfirm('حجم سوزن انژکتور فعلی');
        break;
      case 'oldPressure':
        this.presentActiveAlertConfirm('فشار پمپ بنزین برحسب psi');
        break;
      case 'newPressure':
        this.presentActiveAlertConfirm('فشار پمپ بنزین هدف که میخواد به آن ارتقا دهید برحسب psi');
        break;

      default:
        break;
    }
  }

  async presentActiveAlertConfirm(msg: string = '') {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توضیحات',
      message: msg,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  checkURL() {
    const url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.tunerPlusInj +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    const url = 'https://www.aparat.com/v/' +
      this.tunerPlusInj;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }
}
